PATCH[252]['rrule'] = None

PATCH[348] = dict(region='matawan', stream='yard',
  notes_en="Leaf pickup is by area, one week at a time (zones match your garbage zone; check the Recycling Calendar or the Recycle Coach app if unsure). Fall 2026 leaf weeks: Area 4 weeks of October 12 and November 9; Area 3 weeks of October 19 and November 16; Area 2 weeks of October 26 and November 30; Area 1 weeks of November 2 and December 7. Boroughwide bundled brush and yard waste in biodegradable paper bags was collected on the first Tuesday of each month from May through October 2026 (last date October 6); no more brush dates are on the 2026 calendar. Borough Hall: 732-566-3898. Hauler (Jersey Specialized Hauling): 732-251-5747.",
  notes_es="Las hojas se recogen por área, una semana a la vez (las zonas coinciden con su zona de basura; si no está seguro, vea el Calendario de Reciclaje o la app Recycle Coach). Semanas de hojas de otoño 2026: Área 4, semanas del 12 de octubre y del 9 de noviembre; Área 3, semanas del 19 de octubre y del 16 de noviembre; Área 2, semanas del 26 de octubre y del 30 de noviembre; Área 1, semanas del 2 de noviembre y del 7 de diciembre. Las ramas atadas y los desechos de jardín en bolsas de papel biodegradables se recogieron en todo el municipio el primer martes de cada mes de mayo a octubre de 2026 (la última fecha fue el 6 de octubre); no hay más fechas de ramas en el calendario de 2026. Alcaldía: 732-566-3898. Compañía de basura (Jersey Specialized Hauling): 732-251-5747.")

PATCH[360] = dict(region='middletown', stream='yard', source_url='https://www.middletownnj.org/612/Leaf-Collection-Fall',
  notes_en="Brush is collected curbside in the spring and leaves in the fall, zone by zone (find your zone at www.middletownnj.org/zonemap); crews take about 10 days per zone. As of October 20, 2026 the township lists the Fall 2026 leaf schedule as coming soon; check www.middletownnj.org/collection for where crews are working. Leaves: loose in a neat row at the curb, not in the road, no bags (bagged leaves are not collected), no brush or grass mixed in, out no more than 1 week before your date, up to 4 cubic yards. Loose leaves can also go to the Middletown Recycling Center free from November 1 to June 1; brush is accepted there free Thursday-Monday 8:30 a.m.-4:30 p.m. Public Works: 732-615-2090.",
  notes_es="Las ramas se recogen en la acera en la primavera y las hojas en el otoño, zona por zona (busque su zona en www.middletownnj.org/zonemap); los equipos tardan unos 10 días por zona. Al 20 de octubre de 2026, el municipio indica que el horario de hojas de otoño 2026 se publicará pronto; vea www.middletownnj.org/collection para saber dónde están trabajando. Hojas: sueltas en una fila ordenada en la acera, no en la calle, sin bolsas (las hojas en bolsas no se recogen), sin ramas ni césped mezclados, no más de 1 semana antes de su fecha, hasta 4 yardas cúbicas. También puede llevar hojas sueltas gratis al Centro de Reciclaje de Middletown del 1 de noviembre al 1 de junio; las ramas se aceptan gratis allí de jueves a lunes de 8:30 a.m. a 4:30 p.m. Obras Públicas: 732-615-2090.")

PATCH[368] = dict(region='monmouth-beach', stream='bulk',
  notes_en="Bulk pickup is on Wednesdays, by appointment only: register through the Bulk Pickup link on the borough home page (www.monmouthbeach.org) by 2:30 p.m. the Tuesday before. Put items at the curb the day before pickup. Four pickups per household per year; metals and appliances are picked up. Only a reasonable amount is taken (not the contents of a whole garage, basement or house), and no construction or demolition debris. No pickup on Thanksgiving, Christmas or New Year's Day. Borough Hall: 732-229-2204 ext. 1001. Public Works: 732-229-5513.",
  notes_es="La recogida de objetos grandes es los miércoles, solo con cita: inscríbase con el enlace Bulk Pickup en la página principal del municipio (www.monmouthbeach.org) antes de las 2:30 p.m. del martes anterior. Saque los artículos a la acera el día antes de la recogida. Cuatro recogidas por hogar al año; se recogen metales y electrodomésticos. Solo se lleva una cantidad razonable (no el contenido completo de un garaje, sótano o casa) y no se aceptan escombros de construcción o demolición. No hay recogida el Día de Acción de Gracias, Navidad ni Año Nuevo. Alcaldía: 732-229-2204, ext. 1001. Obras Públicas: 732-229-5513.")

PATCH[369] = dict(region='monmouth-beach', stream='yard',
  notes_en="Leaf pickup runs from October until January. Rake leaves loose to the curb; they are picked up with a vacuum, so do not mix in or pile branches, twigs or anything else on top. No set day per street is published. Public Works: 732-229-5513.",
  notes_es="La recogida de hojas va de octubre hasta enero. Rastrille las hojas sueltas hasta la acera; se recogen con una aspiradora, así que no mezcle ni ponga encima ramas, ramitas ni otra cosa. No se publica un día fijo por calle. Obras Públicas: 732-229-5513.")

PATCH[376] = dict(region='neptune-city', stream='bulk',
  notes_en="Up to 3 bulk items (couch, mattress and the like) go out with your second trash pickup of the week: Thursday for Zone 1 (east of Union Avenue), Friday for Zone 2 (west of Union Avenue). Mattresses and box springs must be wrapped in plastic; rugs cut, rolled and tied in bundles of 30 lb or less. Not taken with trash: refrigeration units, TVs, computer monitors, computers and electronics, concrete, asphalt, brush or leaves. No garbage or recycling collection on Thanksgiving, Christmas, New Year's Day or July 4. Public Works: 732-775-1607.",
  notes_es="Hasta 3 objetos grandes (sofá, colchón y similares) se sacan con su segunda recogida de basura de la semana: jueves para la Zona 1 (al este de Union Avenue), viernes para la Zona 2 (al oeste de Union Avenue). Los colchones y bases de cama deben ir envueltos en plástico; las alfombras cortadas, enrolladas y atadas en paquetes de 30 lb o menos. No se llevan con la basura: equipos de refrigeración, televisores, monitores, computadoras y electrónicos, concreto, asfalto, ramas ni hojas. No hay recogida de basura ni reciclaje el Día de Acción de Gracias, Navidad, Año Nuevo ni el 4 de julio. Obras Públicas: 732-775-1607.")

NEW.append(dict(region='neptune-city', stream='yard', source_url='https://www.neptunecitynj.com/public-works/pages/pick-information',
  weekday=1, week_pattern='weekly', dtstart='2026-03-02', rrule='FREQ=WEEKLY;BYDAY=MO;BYMONTH=3,4,5,6,7,8,9,10,11;UNTIL=20261130',
  overrides=[{'date': '2026-05-25', 'to': '2026-05-26', 'reason': 'Memorial Day'}, {'date': '2026-09-07', 'to': '2026-09-08', 'reason': 'Labor Day'}],
  notes_en="Brush is picked up every Monday from March through November (if Monday is a holiday, on Tuesday); none in December, January or February. Stack brush neatly, cut to 6 ft or shorter. The same Monday pickup takes wood scraps from your own work (pile up to 3x3x3 ft), scrap metal (6 ft / 50 lb pieces; tanks cut in half and cleaned, propane tanks empty with valve removed), broken-up pallets and broken concrete (pieces up to 50 lb, pile up to 3x3x3 ft); keep each material in its own pile. Christmas trees go out on Mondays in December, January and February. Public Works: 732-775-1607.",
  notes_es="Las ramas se recogen todos los lunes de marzo a noviembre (si el lunes es feriado, el martes); no hay recogida en diciembre, enero ni febrero. Apile las ramas ordenadamente, cortadas a 6 pies o menos. La misma recogida del lunes se lleva restos de madera de su propio trabajo (montón de hasta 3x3x3 pies), chatarra (piezas de 6 pies / 50 lb; tanques cortados por la mitad y limpios, tanques de propano vacíos y sin válvula), paletas desarmadas y concreto partido (pedazos de hasta 50 lb, montón de hasta 3x3x3 pies); ponga cada material en su propio montón. Los árboles de Navidad se sacan los lunes de diciembre, enero y febrero. Obras Públicas: 732-775-1607."))

NEW.append(dict(region='neptune-city', stream='yard', source_url='https://www.neptunecitynj.com/public-works/pages/leaves',
  notes_en="Leaves are collected only from April 1 through May 31 and September 15 through December 15. Put them loose at the curb; do not bag them or mix in branches, sticks, grass or other debris. Leaves in open containers or clear plastic bags are no longer accepted. No set day per street is published. Public Works: 732-775-1607.",
  notes_es="Las hojas se recogen solo del 1 de abril al 31 de mayo y del 15 de septiembre al 15 de diciembre. Sáquelas sueltas a la acera; no las ponga en bolsas ni mezcle ramas, palos, césped u otros desechos. Ya no se aceptan hojas en recipientes abiertos ni en bolsas de plástico transparente. No se publica un día fijo por calle. Obras Públicas: 732-775-1607."))

PATCH[386] = dict(region='neptune-township', stream='bulk',
  notes_en="Bulk and brush are collected one zone per week, every month, by your garbage zone (Ocean Grove Zone B goes with Zone B, Ocean Grove Zone C with Zone C). Have items at the curb before 6:00 a.m. on the Monday of your zone's week, no earlier than the weekend before; crews take the whole week. Remaining 2026 weeks: Zone A Nov 2 and Dec 7; Zone B and OG-B Nov 9 and Dec 14; Zone C and OG-C Nov 16 and Dec 21; Zone D Nov 23 and Dec 28 (November is bulk only, no brush). October weeks were A Oct 5, B Oct 12, C Oct 19, D Oct 26. Up to 6 items per household; keep bulk in a separate pile from brush. Mattresses and box springs must be wrapped in plastic; metal must be free of concrete; items with freon must be paid for and scheduled with the DPW office. Not taken at the curb: electronics, construction material, concrete or brick, wood and fencing, tires, oil paint, hazardous waste. No special pick-ups or move-out cleanups. Public Works: 732-775-8797.",
  notes_es="Los objetos grandes y las ramas se recogen una zona por semana, cada mes, según su zona de basura (Ocean Grove Zona B va con la Zona B y Ocean Grove Zona C con la Zona C). Tenga los artículos en la acera antes de las 6:00 a.m. del lunes de la semana de su zona, no antes del fin de semana anterior; los equipos tardan toda la semana. Semanas que quedan en 2026: Zona A, 2 de noviembre y 7 de diciembre; Zona B y OG-B, 9 de noviembre y 14 de diciembre; Zona C y OG-C, 16 de noviembre y 21 de diciembre; Zona D, 23 de noviembre y 28 de diciembre (noviembre es solo objetos grandes, sin ramas). En octubre fueron: A el 5, B el 12, C el 19 y D el 26. Hasta 6 artículos por hogar; ponga los objetos grandes en un montón separado de las ramas. Los colchones y bases de cama deben ir envueltos en plástico; el metal sin concreto; los artículos con freón se pagan y se programan con la oficina de Obras Públicas. No se recogen en la acera: electrónicos, materiales de construcción, concreto o ladrillo, madera y cercas, llantas, pintura de aceite ni desechos peligrosos. No hay recogidas especiales ni de mudanzas. Obras Públicas: 732-775-8797.")

PATCH[387] = dict(region='neptune-township', stream='yard',
  notes_en="Brush goes out with your zone's monthly bulk and brush week (see the bulk entry for dates): loose at the curb by 6:00 a.m. on the Monday of your zone's week, no earlier than the weekend before, and never after your week. Remaining 2026 brush weeks: Zone A Dec 7; Zone B and OG-B Dec 14; Zone C and OG-C Dec 21; Zone D Dec 28. There is no brush collection in November (leaf season). Brush includes tree parts, shrubs, trimmings, vines, bamboo, sea grass, pumpkins, cornstalks and hay bales, cut to 4 ft or less; limbs over 12 in. thick are not taken. No bags or containers. Grass is never picked up; it can go free to the Recycling Center, 2201 Heck Ave. Public Works: 732-775-8797.",
  notes_es="Las ramas se sacan en la semana mensual de objetos grandes y ramas de su zona (vea la entrada de objetos grandes para las fechas): sueltas en la acera antes de las 6:00 a.m. del lunes de la semana de su zona, no antes del fin de semana anterior, y nunca después de su semana. Semanas de ramas que quedan en 2026: Zona A, 7 de diciembre; Zona B y OG-B, 14 de diciembre; Zona C y OG-C, 21 de diciembre; Zona D, 28 de diciembre. No hay recogida de ramas en noviembre (temporada de hojas). Las ramas incluyen partes de árboles, arbustos, recortes, enredaderas, bambú, hierba de mar, calabazas, tallos de maíz y pacas de heno, cortados a 4 pies o menos; no se llevan troncos de más de 12 pulgadas de grosor. Sin bolsas ni recipientes. El césped nunca se recoge; puede llevarlo gratis al Centro de Reciclaje, 2201 Heck Ave. Obras Públicas: 732-775-8797.")

PATCH[388] = dict(region='neptune-township', stream='yard',
  notes_en="Leaf collection runs from the first week of November through December 31, 2026, with no set schedule by street (delays are possible at high volume). Put leaves loose in a pile at the curb, no more than 4 ft into the street, away from storm drains, with no branches, brush, weeds, plants or debris mixed in. Bagged or containerized leaves are not picked up. From December, keep leaves in a separate pile from brush. Public Works: 732-775-8797.",
  notes_es="La recogida de hojas va de la primera semana de noviembre hasta el 31 de diciembre de 2026, sin horario fijo por calle (puede haber retrasos con mucho volumen). Ponga las hojas sueltas en un montón en la acera, a no más de 4 pies dentro de la calle, lejos de las alcantarillas y sin ramas, maleza, plantas ni desechos. Las hojas en bolsas o recipientes no se recogen. Desde diciembre, ponga las hojas en un montón separado de las ramas. Obras Públicas: 732-775-8797.")

PATCH[403] = dict(region='oceanport', stream='bulk',
  notes_en="Bulk and metal pickups are by appointment through Public Works: submit the Citizen Request form on the borough home page (www.oceanportboro.com) describing your items, and staff reply within a day or two (excluding weekends) with a pickup date. Do not put anything out until you have a date; put items out no earlier than 6 p.m. the evening before and by 7:00 a.m. that day. Bulk (furniture, carpeting, mattresses) is limited to 3 items, bundles or bags regardless of size. Metal and appliances (remove all doors) and tires are picked up the same way. Building materials (cabinets, vanities, sheetrock, tile, wood, windows, doors) and construction debris are not taken. No pickups on July 4, Thanksgiving, Christmas or New Year's Day. Public Works: 732-222-8221 ext. 1021.",
  notes_es="Los objetos grandes y el metal se recogen con cita a través de Obras Públicas: llene el formulario Citizen Request en la página principal del municipio (www.oceanportboro.com) describiendo sus artículos, y el personal responde en uno o dos días (sin contar fines de semana) con una fecha. No saque nada hasta tener fecha; saque los artículos no antes de las 6 p.m. de la noche anterior y antes de las 7:00 a.m. ese día. Los objetos grandes (muebles, alfombras, colchones) se limitan a 3 artículos, paquetes o bolsas, sin importar el tamaño. El metal y los electrodomésticos (quíteles todas las puertas) y las llantas se recogen de la misma manera. No se llevan materiales de construcción (gabinetes, tocadores, paneles de yeso, azulejos, madera, ventanas, puertas) ni escombros de obra. No hay recogidas el 4 de julio, Día de Acción de Gracias, Navidad ni Año Nuevo. Obras Públicas: 732-222-8221, ext. 1021.")

PATCH[404] = dict(region='oceanport', stream='yard',
  notes_en="Brush is collected after the first Monday of each month, April through November (2026: November 2 is the last start date). Keep brush separate from leaves (mixed piles are not collected), in front of your own property only, more than 10 ft from storm drains. Branches up to 5 ft long and 3 in. thick; up to 3 cubic yards per pickup (about 3 ft wide x 3 ft high x 9 ft long). Not collected: sod, dirt, grass clippings, bamboo, lumber, logs, stumps, roots or tree-contractor debris. If your brush was missed, call 732-222-8221 ext. 1021 or use the Brush Pickup Request Form.",
  notes_es="Las ramas se recogen después del primer lunes de cada mes, de abril a noviembre (2026: el 2 de noviembre es la última fecha de inicio). Mantenga las ramas separadas de las hojas (los montones mezclados no se recogen), solo frente a su propiedad y a más de 10 pies de las alcantarillas. Ramas de hasta 5 pies de largo y 3 pulgadas de grosor; hasta 3 yardas cúbicas por recogida (unos 3 pies de ancho x 3 de alto x 9 de largo). No se recogen: césped en panes, tierra, césped cortado, bambú, madera, troncos, tocones, raíces ni desechos de contratistas de árboles. Si no recogieron sus ramas, llame al 732-222-8221, ext. 1021, o use el formulario Brush Pickup Request.")

PATCH[405] = dict(region='oceanport', stream='yard',
  notes_en="Leaves are collected curbside only in April, October, November and December, continually through those months, weather permitting; there are no zones. Do not put leaves out at other times, do not use plastic bags, and keep piles more than 10 ft from storm drains. Grass clippings are not accepted. Landscapers must remove their own debris. Public Works: 732-222-8221 ext. 1021.",
  notes_es="Las hojas se recogen en la acera solo en abril, octubre, noviembre y diciembre, de forma continua durante esos meses si el tiempo lo permite; no hay zonas. No saque hojas en otros meses, no use bolsas de plástico y mantenga los montones a más de 10 pies de las alcantarillas. No se acepta césped cortado. Los jardineros deben llevarse sus propios desechos. Obras Públicas: 732-222-8221, ext. 1021.")

PATCH[406] = dict(region='oceanport', stream='other',
  notes_en="Electronics (TVs of all sizes, computers, keyboards and mice, stereo components and more) are picked up on Fridays by appointment as part of the bulk and metal program: schedule on www.oceanportboro.com or call Public Works at 732-222-8221 ext. 1021. Up to 3 items per pickup. Electronics may not go out with regular trash.",
  notes_es="Los electrónicos (televisores de todos los tamaños, computadoras, teclados y ratones, equipos de sonido y más) se recogen los viernes con cita, como parte del programa de objetos grandes y metal: programe en www.oceanportboro.com o llame a Obras Públicas al 732-222-8221, ext. 1021. Hasta 3 artículos por recogida. Los electrónicos no pueden ir con la basura normal.")
PATCH[403]['source_url'] = 'https://www.oceanportboro.com/resident/trash'
PATCH[404]['source_url'] = 'https://www.oceanportboro.com/resident/trash'
PATCH[405]['source_url'] = 'https://www.oceanportboro.com/resident/trash'
PATCH[406]['source_url'] = 'https://www.oceanportboro.com/resident/trash'

_RB_DAYS = [('Monday', 'lunes', 9, 14), ('Tuesday', 'martes', 10, 15), ('Wednesday', 'miércoles', 11, 16), ('Thursday', 'jueves', 12, 17), ('Friday', 'viernes', 13, 18)]
for _n, (_d, _des, _nov, _dec) in enumerate(_RB_DAYS, start=1):
    PATCH[411 + _n] = dict(region='red-bank', stream='yard',
      notes_en=f"Zone {_n} (see the Street Zone Map on the Public Utilities page): brush and leaves are collected one day a month, on the {_d} of the 2nd full week of the month. Brush runs April through October; fall leaves are November and December. Remaining 2026 leaf days for Zone {_n}: {_d}, November {_nov} and {_d}, December {_dec}. Leaves may go out loose or in biodegradable bags; only leaves are taken, so piles with other debris are left. Yard waste that is not in a container may be at the curb only during the 7 days before your scheduled day (Ordinance 434-8), and summonses are issued for violations. Do not block catch basins. Public Works: 732-530-2770.",
      notes_es=f"Zona {_n} (vea el mapa de zonas en la página de Servicios Públicos): las ramas y hojas se recogen un día al mes, el {_des} de la 2.a semana completa del mes. Las ramas van de abril a octubre; las hojas de otoño en noviembre y diciembre. Días de hojas que quedan en 2026 para la Zona {_n}: {_des} {_nov} de noviembre y {_des} {_dec} de diciembre. Las hojas pueden ir sueltas o en bolsas biodegradables; solo se llevan hojas, así que los montones con otros desechos se dejan. Los desechos de jardín que no estén en un recipiente solo pueden estar en la acera durante los 7 días antes de su día programado (Ordenanza 434-8), y se dan multas por violaciones. No bloquee las alcantarillas. Obras Públicas: 732-530-2770.")

PATCH[417] = dict(region='red-bank', stream='other',
  notes_en="Christmas trees are collected curbside from January 1 through the second week of February. Remove all decorations, ornaments, tinsel and lights; artificial trees are not collected. Public Works: 732-530-2770.",
  notes_es="Los árboles de Navidad se recogen en la acera del 1 de enero hasta la segunda semana de febrero. Quite todos los adornos, esferas, escarcha y luces; los árboles artificiales no se recogen. Obras Públicas: 732-530-2770.")

PATCH[429] = dict(region='rumson', stream='bulk',
  notes_en="Curbside bulk pickup is by appointment only, on the 1st and 3rd Wednesdays of the month, January through October; there are no bulk pickups in November and December (the 2026 season ended with October 21). Schedule at least one week ahead with the Schedule Bulk Pickup link on www.rumsonnj.gov. Two pickups per household per year, up to 5 cubic yards each, plus one extra pickup when moving in or out (call 732-842-3300). Appliances, computers and TVs may be included; remove doors from refrigerators and freezers. Put items out no sooner than the day before your Wednesday. Not taken: construction materials, concrete or asphalt, hazardous waste, recyclables, propane tanks, fuel containers, pipe with concrete attached. Do not bring bulk to the Recycling Center. Public Works: 732-842-8941.",
  notes_es="La recogida de objetos grandes en la acera es solo con cita, el 1.er y 3.er miércoles del mes, de enero a octubre; no hay recogidas en noviembre ni diciembre (la temporada 2026 terminó el 21 de octubre). Programe con al menos una semana de anticipación con el enlace Schedule Bulk Pickup en www.rumsonnj.gov. Dos recogidas por hogar al año, de hasta 5 yardas cúbicas cada una, más una recogida extra al mudarse (llame al 732-842-3300). Se pueden incluir electrodomésticos, computadoras y televisores; quite las puertas de refrigeradores y congeladores. Saque los artículos no antes del día anterior a su miércoles. No se llevan: materiales de construcción, concreto o asfalto, desechos peligrosos, reciclables, tanques de propano, recipientes de combustible ni tubos con concreto. No lleve objetos grandes al Centro de Reciclaje. Obras Públicas: 732-842-8941.")

PATCH[435] = dict(region='sea-bright', stream='other',
  notes_en="Christmas trees: put them at the curb during the month of January for pickup. Public Works: 732-842-0099 ext. 136.",
  notes_es="Árboles de Navidad: sáquelos a la acera durante el mes de enero para que los recojan. Obras Públicas: 732-842-0099, ext. 136.")

PATCH[436] = dict(region='sea-bright', stream='other',
  notes_en="Appliances are picked up by appointment only, for $25 per appliance. Before putting anything out, submit the Appliance Removal Form and fee at Borough Hall, 1099 Ocean Avenue (732-842-0099 ext. 119). Public Works: 732-842-0099 ext. 136.",
  notes_es="Los electrodomésticos se recogen solo con cita, por $25 cada uno. Antes de sacar nada, entregue el formulario Appliance Removal Form y la tarifa en la alcaldía, 1099 Ocean Avenue (732-842-0099, ext. 119). Obras Públicas: 732-842-0099, ext. 136.")

PATCH[447] = dict(region='union-beach', stream='other',
  notes_en="Metals, appliances and electronics (TVs, computers, microwaves, air conditioners, cameras, phones, copiers and more) should be brought to the Recycling Center; remove refrigerator doors first. If you cannot get them there, call Public Works at 732-264-1133 to arrange a curbside pickup. The Recycling Center also takes tires without rims, used motor oil in sealed containers, car batteries, ink cartridges and small amounts of concrete. Paint is never accepted.",
  notes_es="Los metales, electrodomésticos y electrónicos (televisores, computadoras, microondas, aires acondicionados, cámaras, teléfonos, copiadoras y más) deben llevarse al Centro de Reciclaje; quite primero las puertas de los refrigeradores. Si no puede llevarlos, llame a Obras Públicas al 732-264-1133 para que los recojan en la acera. El Centro de Reciclaje también acepta llantas sin rin, aceite de motor usado en recipientes sellados, baterías de carro, cartuchos de tinta y pequeñas cantidades de concreto. Nunca se acepta pintura.")

PATCH[455] = dict(region='west-long-branch', stream='bulk', source_url='https://www.westlongbranch.org/1347/Bulk-Item-Collection',
  notes_en="Bulky metal (washers, dryers and other miscellaneous metal) goes to the curb during the 4th week of each month, borough-wide. Remaining 2026 weeks: the weeks of October 26, November 23 and December 21 (4th Monday of the month). No bulk pickup on New Year's Day, Independence Day, Election Day, Thanksgiving or Christmas. Public Works: 732-571-5967.",
  notes_es="El metal grande (lavadoras, secadoras y otros metales) se saca a la acera durante la 4.a semana de cada mes, en todo el municipio. Semanas que quedan en 2026: las semanas del 26 de octubre, 23 de noviembre y 21 de diciembre (4.o lunes del mes). No hay recogida de objetos grandes el Año Nuevo, Día de la Independencia, Día de las elecciones, Día de Acción de Gracias ni Navidad. Obras Públicas: 732-571-5967.")

PATCH[456] = dict(region='west-long-branch', stream='yard', source_url='https://www.westlongbranch.org/1343/Leaf-Brush-Collection',
  notes_en="Loose leaves are collected from November 3 to December 12. Rake them to the curb with nothing else mixed in or on top (no branches or twigs), and do not put brush out during this period. Leaves or brush put out outside the scheduled dates are not collected and get a Notice of Violation. Grass and thatch clippings are never picked up. Landscapers must remove their own debris. Public Works: 732-571-5967.",
  notes_es="Las hojas sueltas se recogen del 3 de noviembre al 12 de diciembre. Rastríllelas hasta la acera sin nada mezclado ni encima (sin ramas ni ramitas) y no saque ramas durante este periodo. Las hojas o ramas sacadas fuera de las fechas programadas no se recogen y reciben un aviso de violación. El césped cortado nunca se recoge. Los jardineros deben llevarse sus propios desechos. Obras Públicas: 732-571-5967.")

PATCH[457] = dict(region='west-long-branch', stream='yard', source_url='https://www.westlongbranch.org/1343/Leaf-Brush-Collection',
  notes_en="Brush is collected from December 12 through November 3 (that is, all year except the fall leaf period, November 3 to December 12). Do not mix brush with leaves. Branches and limbs up to 6 in. in diameter (Ordinance 15-2.2); bamboo is not collected. Brush put out during leaf season gets a Notice of Violation. Public Works: 732-571-5967.",
  notes_es="Las ramas se recogen del 12 de diciembre al 3 de noviembre (es decir, todo el año excepto el periodo de hojas de otoño, del 3 de noviembre al 12 de diciembre). No mezcle ramas con hojas. Ramas de hasta 6 pulgadas de diámetro (Ordenanza 15-2.2); el bambú no se recoge. Las ramas sacadas en temporada de hojas reciben un aviso de violación. Obras Públicas: 732-571-5967.")

for _key, _note, _wd, _by, _start, _ovr in (
        ('trash:north-zone', 'North Zone: collection from 6:00 a.m.; see official street listing', 4, 'TH', '2026-01-01', [{'date': '2026-01-01', 'to': None, 'reason': "New Year's Day"}, {'date': '2026-11-26', 'to': None, 'reason': 'Thanksgiving Day'}]),
        ('trash:south-zone', 'South Zone: collection from 6:00 a.m.; see official street listing', 5, 'FR', '2026-01-02', [{'date': '2026-12-25', 'to': None, 'reason': 'Christmas Day'}, {'date': '2027-01-01', 'to': None, 'reason': "New Year's Day"}])):
    _zn = 'North' if _wd == 4 else 'South'
    _d, _des, _zes = ('Thursday', 'jueves', 'Norte') if _wd == 4 else ('Friday', 'viernes', 'Sur')
    NEW.append(dict(region='west-long-branch', stream='bulk', source_url='https://www.westlongbranch.org/1347/Bulk-Item-Collection',
      area_key=_key, area_note=_note, weekday=_wd, week_pattern='weekly', dtstart=_start, rrule=f'FREQ=WEEKLY;BYDAY={_by};UNTIL=20270131', overrides=_ovr,
      notes_en=f"{_zn} Zone: bulky furniture (things you sit, sleep or eat on) goes out on your second garbage day each week, {_d}; limit 3 items. No bulk pickup on New Year's Day, Independence Day, Election Day, Thanksgiving or Christmas. Public Works: 732-571-5967.",
      notes_es=f"Zona {_zes}: los muebles grandes (para sentarse, dormir o comer) se sacan en su segundo día de basura cada semana, el {_des}; límite de 3 artículos. No hay recogida de objetos grandes el Año Nuevo, Día de la Independencia, Día de las elecciones, Día de Acción de Gracias ni Navidad. Obras Públicas: 732-571-5967."))
